ALTER TABLE "bookings" ADD COLUMN "photo_consent_decision" varchar(32);--> statement-breakpoint
ALTER TABLE "bookings" ADD COLUMN "photo_consent_signer_name" varchar(255);--> statement-breakpoint
ALTER TABLE "bookings" ADD COLUMN "photo_consent_version" varchar(32);--> statement-breakpoint
ALTER TABLE "bookings" ADD COLUMN "photo_consent_recorded_at" timestamp with time zone;--> statement-breakpoint
ALTER TABLE "bookings" ADD CONSTRAINT "bookings_photo_consent_valid" CHECK (("bookings"."photo_consent_decision" IS NULL AND "bookings"."photo_consent_signer_name" IS NULL AND "bookings"."photo_consent_version" IS NULL AND "bookings"."photo_consent_recorded_at" IS NULL) OR ("bookings"."photo_consent_decision" = 'declined' AND "bookings"."photo_consent_signer_name" IS NULL AND "bookings"."photo_consent_version" IS NOT NULL AND "bookings"."photo_consent_recorded_at" IS NOT NULL) OR ("bookings"."photo_consent_decision" IN ('adult_only', 'guardian_for_minor') AND "bookings"."photo_consent_signer_name" IS NOT NULL AND length(trim("bookings"."photo_consent_signer_name")) >= 2 AND "bookings"."photo_consent_version" IS NOT NULL AND "bookings"."photo_consent_recorded_at" IS NOT NULL));